def factorial(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

def fizzbuzz(n):
    o=[]
    for i in range(1,n+1):
        if i%15==0: o.append('FizzBuzz')
        elif i%3==0: o.append('Fizz')
        elif i%5==0: o.append('Buzz')
        else: o.append(str(i))
    return o

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def sum_list(lst):
    t = 0
    for x in lst:
        t += x
    return t

def max_of(lst):
    m = lst[0]
    for x in lst[1:]:
        if x > m: m = x
    return m

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def flatten(lst):
    o = []
    for sub in lst:
        for x in sub:
            o.append(x)
    return o

def second_largest(lst):
    u = sorted(set(lst))
    return u[-2]

def char_count(s):
    d = {}
    for c in s:
        d[c] = d.get(c,0)+1
    return d

def to_snake(s):
    o = ''
    for c in s:
        if c.isupper(): o += '_' + c.lower()
        else: o += c
    return o
